implementation:
#include <linux/ftrace_event.h>
#include <linux/irqflags.h>
#include <linux/preempt.h>

void handle_syscall_trace_entry(void *data, struct pt_regs *regs, long id) {
    int i;
    struct ftrace_event_file *file;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    struct trace_entry *entry;
    unsigned long flags;
    unsigned int pc;

    if (!regs) {
        return;
    }

    id = pt_regs_SYSCALL(regs);

    file = find_event_file(data, id);
    if (!file || !file->enabled) {
        return;
    }

    buffer = file->ring_buffer;
    if (!buffer) {
        return;
    }

    flags = raw_local_save_flags();
    pc = preempt_count();

    event = ring_buffer_lock_reserve(buffer, sizeof(*entry));
    if (!event) {
        return;
    }

    entry = ring_buffer_event_data(event);
    entry->type = TRACE_SYSCALL_ENTRY;
    entry->pid = current->pid;

    for (i = 0; i < 6; i++) {
        entry->fields[i] = pt_regs_get_arg(regs, i);
    }

    entry->id = id;
    entry->__data[0] = flags;
    entry->__data[1] = pc;

    ring_buffer_unlock_commit(buffer, event);
}
